num = 0
while True:
    num += 1
    if num == 3:
        continue  # skip 3
    if num > 4:
        break     # stop at 5
    print(num, end=" ")
print()

# Demonstration of break skipping loop-else
x = 1
while x < 5:
    if x == 3:
        print("Found 3, breaking!")
        break
    x += 1
else:
    print("This won't print because break occurred")

